In our codebase, we have a legacy module at 'src/legacy/order-processor.js' that handles order processing using nested callbacks. It's becoming unmaintainable. Please refactor it to use async/await. The file currently uses the 'request' library to call an external API, and has a callback pyramid. I need the refactored version to be placed in 'src/modern/order-processor.js'. Here's the current content:

```js
const request = require('request');

function processOrder(orderId, callback) {
  request.get(`https://api.example.com/orders/${orderId}`, (err, res, body) => {
    if (err) return callback(err);
    if (res.statusCode !== 200) return callback(new Error('API error'));
    const order = JSON.parse(body);
    request.post('https://api.example.com/validate', { json: { order } }, (err, res, body) => {
      if (err) return callback(err);
      if (res.statusCode !== 200) return callback(new Error('Validation failed'));
      request.post('https://api.example.com/process', { json: { orderId: order.id } }, (err, res) => {
        if (err) return callback(err);
        if (res.statusCode !== 200) return callback(new Error('Processing failed'));
        callback(null, { success: true });
      });
    });
  });
}

module.exports = { processOrder };
```

Please refactor it to use async/await, using the 'axios' library instead of 'request' (which is deprecated). Also, ensure proper error handling with try/catch. Provide the complete new file content.

Now I'll refactor the code. Here's the refactored file content for 'src/modern/order-processor.js':

```js
const axios = require('axios');

async function processOrder(orderId) {
  try {
    const orderResponse = await axios.get(`https://api.example.com/orders/${orderId}`);
    const order = orderResponse.data;

    const validationResponse = await axios.post('https://api.example.com/validate', { order });
    if (validationResponse.status !== 200) {
      throw new Error('Validation failed');
    }

    const processResponse = await axios.post('https://api.example.com/process', { orderId: order.id });
    if (processResponse.status !== 200) {
      throw new Error('Processing failed');
    }

    return { success: true };
  } catch (error) {
    throw error;
  }
}

module.exports = { processOrder };
```

Key changes: replaced `request` with `axios`, flattened the callbacks into async/await, and wrapped in try/catch to propagate errors. The function now returns a Promise instead of using a callback. Also, note that axios throws errors on non-2xx status codes automatically, but I kept explicit checks for clarity. You can remove the explicit status checks if you prefer. But the code is functionally equivalent. Let me know if you need any adjustments.

