{"filename": "eventEmitter.js", "content": "class EventEmitter {
  constructor() {
    this.events = new Map();
  }

  subscribe(eventName, callback) {
    if (!this.events.has(eventName)) {
      this.events.set(eventName, new Set());
    }
    const callbacks = this.events.get(eventName);
    if (callbacks.has(callback)) {
      throw new Error(`Callback already subscribed to ${eventName}`);
    }
    callbacks.add(callback);
    return () => this.unsubscribe(eventName, callback);
  }

  unsubscribe(eventName, callback) {
    if (!this.events.has(eventName)) {
      throw new Error(`Event ${eventName} does not exist`);
    }
    this.events.get(eventName).delete(callback);
  }

  emit(eventName, ...args) {
    if (!this.events.has(eventName)) {
      console.warn(`Event ${eventName} does not exist`);
      return;
    }
    this.events.get(eventName).forEach(callback => callback(...args));
  }
}

module.exports = EventEmitter;"}

