def parse_config(json_str, schema):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")
    return _apply_schema(data, schema)

def _apply_schema(data, schema):
    result = {}
    for key, default in schema.items():
        if key in data:
            if isinstance(default, dict) and not isinstance(data[key], dict):
                raise ValueError(f"Key '{key}' expected object")
            if isinstance(default, dict):
                result[key] = _apply_schema(data[key], default)
            else:
                result[key] = data[key]
        else:
            result[key] = default
    return result
"}

