	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		jobs <- scanner.Text()
	}

	close(jobs)
	wg.Wait()
	close(results)

	// Print results
	for result := range results {
		fmt.Println(result)
