```python
import os
from pathlib import Path
import argparse

def scan_directory(path, min_size_mb):
    min_size_bytes = max(0, min_size_mb) * 1024 * 1024
    files = []
    total_size = 0
    for root, dirs, filenames in os.walk(path):
        for name in filenames:
            file_path = Path(root) / name
            try:
                size = file_path.stat().st_size
            except PermissionError:
                continue
            if size >= min_size_bytes:
                files.append({'path': str(file_path), 'size_bytes': size})
                total_size += size
    return {'files': files, 'total_size_bytes': total_size, 'count': len(files)}

def main():
    parser = create_parser()
    args = parser.parse_args()
    result = scan_directory(args.path, args.min_size)
    if args.json:
        import json
        print(json.dumps(result))
    else:
        print(f"Found {result['count']} files larger than {args.min_size} MB")
        for f in result['files']:
            print(f"{f['path']} ({f['size_bytes']} bytes)")
        print(f"Total size: {result['total_size_bytes']} bytes")

if __name__ == '__main__':
    main()
```

This implementation handles permission errors gracefully and uses a maximum with 0 to avoid negative min_size. The output format is simple and matches the spec.

