import { prisma } from './prisma';

export default {
  Query: {
    users: () => prisma.user.findMany({ orderBy: { createdAt: 'desc' } }),
    user: (_: any, { id }: { id: string }) => prisma.user.findUnique({ where: { id } }),
  },
  Mutation: {
    createUser: async (_: any, { input }: { input: { name: string; email: string } }) => {
      const errors = [];
      if (!input.name || input.name.trim() === '') errors.push({ field: 'name', message: 'Name is required' });
      if (!input.email || !/^[^@]+@[^@]+$/.test(input.email)) errors.push({ field: 'email', message: 'Email format is invalid' });
      if (errors.length > 0) return { __typename: 'ValidationErrors', errors };
      const user = await prisma.user.create({ data: { name: input.name, email: input.email } });
      return { __typename: 'User', ...user };
    }
  }
};

